const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const go=(text,target,kind='primary')=>`<a class="btn ${kind}" href="#${target}">${text}</a>`;
const action=(text,kind='primary',name='demo')=>`<button class="btn ${kind}" data-action="${name}">${text}</button>`;
const badge=(text,kind='good')=>`<span class="badge ${kind}"><i class="dot"></i>${text}</span>`;
const note=(title,body='',kind='')=>`<div class="note ${kind}"><strong>${title}</strong>${body?`<p>${body}</p>`:''}</div>`;
const field=(label,value='',type='text',hint='')=>`<div class="field"><label class="label">${label}<input class="input" type="${type}" value="${esc(value)}" ${type==='email'?'autocomplete="off"':''}></label>${hint?`<small>${hint}</small>`:''}</div>`;
const select=(label,opts)=>`<div class="field"><label class="label">${label}<select>${opts.map(x=>`<option>${x}</option>`).join('')}</select></label></div>`;
const toggle=(title,sub,on=false)=>`<div class="toggle"><div><strong>${title}</strong><small>${sub}</small></div><button type="button" class="switch ${on?'on':''}" role="switch" aria-checked="${on}" aria-label="${title}" data-action="toggle"></button></div>`;
const table=(headers,rows)=>`<div class="table-wrap"><table class="data-table"><thead><tr>${headers.map(x=>`<th scope="col">${x}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${row.map(x=>`<td>${x}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
const card=(title,body,extra='')=>`<section class="card ${extra}">${title?`<div class="card-title"><h2>${title}</h2></div>`:''}${body}</section>`;
const checkList=items=>`<ul class="checklist">${items.map((x,i)=>`<li><span class="check ${x[2]?'pending':''}">${x[2]?'↗':'✓'}</span><div><strong>${x[0]}</strong><small>${x[1]}</small></div>${x[3]?`<a class="btn link" style="margin-left:auto" href="#${x[3]}">Open →</a>`:''}</li>`).join('')}</ul>`;
const stats=(items)=>`<div class="grid cols${items.length}">${items.map(x=>`<section class="card"><div class="stat-label">${x[0]}<span>↗</span></div><div class="stat-value">${x[1]}</div><div class="stat-foot">${x[2]}</div>${x[3]!==undefined?`<div class="progress"><i style="width:${x[3]}%"></i></div>`:''}</section>`).join('')}</div>`;
const steps=(active)=>`<div class="steps">${['Message','Audience','Preview','Review & send'].map((x,i)=>`<div class="step ${active===i?'active':''}"><span>${i+1}</span>${x}</div>`).join('')}</div>`;
const emailPreview=()=>`<article class="email-preview"><div class="email-meta"><strong>Alpine Paper Co.</strong> &lt;hello@example.com&gt;<br>Subject: A little something for the season ahead</div><div class="email-content"><div class="eyebrow">ALPINE PAPER CO.</div><h2>Good things<br>arrive on paper.</h2><div class="paper-art" role="img" aria-label="Illustrative handwritten stationery card"></div><p>A slower moment. A thoughtful note.<br>Meet the paper goods made for both.</p>${action('Explore the collection','primary','sample-link')}<div class="email-footer">You asked to hear from Alpine Paper Co.<br>Sample mailing address · Your town, CO<br><a href="#preferences">Preferences</a> · <a href="#unsubscribe">Unsubscribe</a></div></div></article>`;
